use super::helpers::compile_ok;

#[test] fn special_names_decimal_comma_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    DECIMAL-POINT IS COMMA.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC 9(3)V99.\nPROCEDURE DIVISION.\n    MOVE 1 TO X.\n    STOP RUN."); }
#[test] fn special_names_alphabet_ascii_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    ALPHABET A-ASC IS ASCII.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC X(5).\nPROCEDURE DIVISION.\n    DISPLAY X.\n    STOP RUN."); }
#[test] fn special_names_alphabet_std1_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    ALPHABET A1 IS STANDARD-1.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC X(5).\nPROCEDURE DIVISION.\n    DISPLAY X.\n    STOP RUN."); }
#[test] fn special_names_combined_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    DECIMAL-POINT IS COMMA\n    ALPHABET A1 IS STANDARD-1.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC X(5).\nPROCEDURE DIVISION.\n    DISPLAY X.\n    STOP RUN."); }
#[test] fn special_names_currency_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    CURRENCY SIGN IS \"$\".\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 A PIC $$9.99.\nPROCEDURE DIVISION.\n    MOVE 1 TO A.\n    STOP RUN."); }
#[test] fn special_names_class_numeric_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    CLASS DIGITS IS \"0\" THRU \"9\".\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC X(1).\nPROCEDURE DIVISION.\n    IF X IS DIGITS DISPLAY \"D\" END-IF.\n    STOP RUN."); }
#[test] fn special_names_alphabet_user_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    ALPHABET A2 IS \"A\" \"B\" \"C\" THRU \"Z\".\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC X(5).\nPROCEDURE DIVISION.\n    DISPLAY X.\n    STOP RUN."); }
#[test] fn special_names_symbolic_chars_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    SYMBOLIC CHARACTERS CR IS 13.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC X.\nPROCEDURE DIVISION.\n    MOVE CR TO X.\n    STOP RUN."); }
#[test] fn special_names_env_names_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    CONSOLE IS CRT.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC X(20).\nPROCEDURE DIVISION.\n    DISPLAY X UPON CRT.\n    STOP RUN."); }
#[test] fn special_names_multiple_alphabet_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    ALPHABET A1 IS ASCII\n    ALPHABET A2 IS STANDARD-1.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC X(5).\nPROCEDURE DIVISION.\n    DISPLAY X.\n    STOP RUN."); }
#[test] fn special_names_mnemonics_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    CONSOLE IS CRT.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC X(5).\nPROCEDURE DIVISION.\n    DISPLAY X UPON CRT.\n    STOP RUN."); }
#[test] fn special_names_with_display_compiles() { compile_ok("IDENTIFICATION DIVISION.\nPROGRAM-ID. T.\nENVIRONMENT DIVISION.\nCONFIGURATION SECTION.\nSPECIAL-NAMES.\n    ALPHABET ALP IS ASCII.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 X PIC X(10) VALUE \"ABC\".\nPROCEDURE DIVISION.\n    DISPLAY X.\n    STOP RUN."); }
